CREATE TABLE IF NOT EXISTS admin.import_job (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), state varchar(24) NOT NULL, template_version varchar(40) NOT NULL, source_object_key text NOT NULL, source_sha256 bytea NOT NULL, row_count integer NOT NULL DEFAULT 0, organization_revision_at_validation bigint NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, committed_at timestamptz, result_object_key text, result_sha256 bytea, row_version bigint NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS admin.export_job (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), state varchar(16) NOT NULL, selection_mode varchar(20) NOT NULL, filter_snapshot jsonb, target_manifest_id uuid, authorization_version bigint NOT NULL, policy_revision bigint NOT NULL, organization_revision bigint NOT NULL, purpose text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, result_object_key text, result_sha256 bytea, result_count integer);
